const formatNumber = (value: number) => new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(value || 0);
const formatMoney = (value: number) => `PKR ${new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(value || 0)}`;
const today = new Date().toISOString().slice(0, 10);

function downloadWorkbook(sheets: Record<string, unknown[]>, fileName: string) {
  const workbook = XLSX.utils.book_new();
  Object.entries(sheets).forEach(([name, rows]) => XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(rows.length ? rows : [{ Note: "Not provided" }]), name.slice(0, 31)));
  XLSX.writeFile(workbook, fileName);
}

function downloadStyledDailyWorkbook(data: any, date: string) {
  const projects = (data?.projects ?? []).filter((project: any) => project.status === "ACTIVE");
  const testers = (data?.testers ?? []).filter((tester: any) => tester.status === "ACTIVE");
  const leaders = new Map<number, string>((data?.leaders ?? []).map((leader: any) => [leader.leaderId, leader.leader] as [number, string]));
  const performance = data?.performance ?? [];
  const matrix: Array<Array<string | number>> = [["Project", ...projects.map((project: any) => project.name), "Total"]];
  const headerStyle = { fill: { fgColor: { rgb: "D9E1F2" } }, font: { bold: true, color: { rgb: "000000" } }, alignment: { horizontal: "center" } };
  const leaderStyle = { fill: { fgColor: { rgb: "D9EAD3" } }, font: { bold: true, color: { rgb: "000000" } } };
  const totalStyle = { fill: { fgColor: { rgb: "B4C6E7" } }, font: { bold: true, color: { rgb: "0F172A" } } };
  const groups = new Map<string, any[]>();
  for (const tester of testers) { const leader = leaders.get(tester.teamLeaderId) ?? "Unassigned"; const group = groups.get(leader) ?? []; group.push(tester); groups.set(leader, group); }
  groups.forEach((group, leader) => {
    const values = projects.map((project: any) => group.reduce((sum: number, tester: any) => sum + performance.filter((row: any) => row.testerId === tester.id && row.projectId === project.id).reduce((n: number, row: any) => n + Number(row.quantity), 0), 0));
    matrix.push([leader, ...values, values.reduce((sum: number, value: number) => sum + value, 0)]);
    for (const tester of group) { const testerValues = projects.map((project: any) => performance.filter((row: any) => row.testerId === tester.id && row.projectId === project.id).reduce((n: number, row: any) => n + Number(row.quantity), 0)); matrix.push([tester.name, ...testerValues, testerValues.reduce((sum: number, value: number) => sum + value, 0)]); }
  });
  matrix.push(["Grand Total", ...projects.map((project: any) => performance.filter((row: any) => row.projectId === project.id).reduce((n: number, row: any) => n + Number(row.quantity), 0)), performance.reduce((n: number, row: any) => n + Number(row.quantity), 0)]);
  const sheet = XLSX.utils.aoa_to_sheet(matrix); sheet["!cols"] = [{ wch: 24 }, ...projects.map(() => ({ wch: 14 })), { wch: 14 }];
  for (let column = 0; column < matrix[0]!.length; column++) { const cell = sheet[XLSX.utils.encode_cell({ r: 0, c: column })] as any; if (cell) cell.s = headerStyle; }
  let rowIndex = 1; groups.forEach(group => { const cell = sheet[XLSX.utils.encode_cell({ r: rowIndex, c: 0 })] as any; if (cell) cell.s = leaderStyle; for (let column = 1; column < matrix[0]!.length; column++) { const subtotal = sheet[XLSX.utils.encode_cell({ r: rowIndex, c: column })] as any; if (subtotal) subtotal.s = leaderStyle; } rowIndex += group.length + 1; });
  for (let column = 0; column < matrix[0]!.length; column++) { const cell = sheet[XLSX.utils.encode_cell({ r: matrix.length - 1, c: column })] as any; if (cell) cell.s = totalStyle; }
  const workbook = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(workbook, sheet, "Daily Report"); XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(performance.map((row: any) => ({ Date: date, Tester: testers.find((tester: any) => tester.id === row.testerId)?.name ?? "Unknown", "Team Leader": leaders.get(row.teamLeaderId) ?? "Unassigned", Project: projects.find((project: any) => project.id === row.projectId)?.name ?? "Unknown", Quantity: Number(row.quantity) }))), "Raw Data"); XLSX.writeFile(workbook, `Daily_Operations_Report_${date}.xlsx`);
  toast.success("Styled daily report downloaded");
}

type AssistantReportRow = { leader: string; tester: string; superX: number; inception: number; total: number; superXPayout?: number; inceptionPayout?: number; totalPayout?: number };
type AssistantReport = { date: string; stored: number; exceptions: string[]; rows: AssistantReportRow[]; payoutRequested?: boolean };

function reportMatrix(rows: AssistantReportRow[]) {
  const leaderNames = Array.from(new Set(rows.map(row => row.leader)));
  const matrix: Array<Array<string | number>> = [["Project", "Inception", "Super x", "Total"]];
  for (const leader of leaderNames) {
    const group = rows.filter(row => row.leader === leader);
    matrix.push([leader, group.reduce((sum, row) => sum + row.inception, 0), group.reduce((sum, row) => sum + row.superX, 0), group.reduce((sum, row) => sum + row.total, 0)]);
    for (const row of group) matrix.push([row.tester, row.inception, row.superX, row.total]);
  }
  matrix.push(["Grand Total", rows.reduce((sum, row) => sum + row.inception, 0), rows.reduce((sum, row) => sum + row.superX, 0), rows.reduce((sum, row) => sum + row.total, 0)]);
  return matrix;
}

function downloadAssistantWorkbook(report: AssistantReport) {
  const workbook = XLSX.utils.book_new();
  const payoutMode = Boolean(report.payoutRequested);
  const groups = Array.from(new Set(report.rows.map(row => row.leader))).map(leader => ({ leader, rows: report.rows.filter(row => row.leader === leader) }));
  const matrix = payoutMode ? [["Team Leader / Tester", "Role", "Inception OTP", "Inception Payout", "Super X OTP", "Super X Payout", "Total OTP", "Total Payout", "Status"], ...groups.flatMap(group => { const subtotal = group.rows.reduce((a, row) => ({ inception: a.inception + row.inception, inceptionPay: a.inceptionPay + (row.inceptionPayout ?? 0), superX: a.superX + row.superX, superXPay: a.superXPay + (row.superXPayout ?? 0), total: a.total + row.total, totalPay: a.totalPay + (row.totalPayout ?? 0) }), { inception: 0, inceptionPay: 0, superX: 0, superXPay: 0, total: 0, totalPay: 0 }); return [[group.leader, "Team Leader", subtotal.inception, subtotal.inceptionPay, subtotal.superX, subtotal.superXPay, subtotal.total, subtotal.totalPay, "Team Subtotal"], ...group.rows.map(row => [row.tester, "Tester", row.inception, row.inceptionPayout ?? 0, row.superX, row.superXPayout ?? 0, row.total, row.totalPayout ?? 0, "Active"])] }), ["GRAND TOTAL", "Category Summary", report.rows.reduce((s, r) => s + r.inception, 0), report.rows.reduce((s, r) => s + (r.inceptionPayout ?? 0), 0), report.rows.reduce((s, r) => s + r.superX, 0), report.rows.reduce((s, r) => s + (r.superXPayout ?? 0), 0), report.rows.reduce((s, r) => s + r.total, 0), report.rows.reduce((s, r) => s + (r.totalPayout ?? 0), 0), "Overall"]] : reportMatrix(report.rows);
  const sheet = XLSX.utils.aoa_to_sheet(matrix);
  sheet["!cols"] = payoutMode ? [{ wch: 24 }, { wch: 18 }, { wch: 14 }, { wch: 18 }, { wch: 14 }, { wch: 18 }, { wch: 14 }, { wch: 18 }, { wch: 18 }] : [{ wch: 24 }, { wch: 14 }, { wch: 16 }, { wch: 14 }];
  XLSX.utils.book_append_sheet(workbook, sheet, "Formatted Report");
  XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(groups.map(group => ({ "Team Leader": group.leader, "Inception OTP": group.rows.reduce((s, r) => s + r.inception, 0), "Inception Payout": group.rows.reduce((s, r) => s + (r.inceptionPayout ?? 0), 0), "Super X OTP": group.rows.reduce((s, r) => s + r.superX, 0), "Super X Payout": group.rows.reduce((s, r) => s + (r.superXPayout ?? 0), 0), "Total OTP": group.rows.reduce((s, r) => s + r.total, 0), "Total Payout": group.rows.reduce((s, r) => s + (r.totalPayout ?? 0), 0) }))), "Team Leaders");
  XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(report.rows.map(row => ({ "Team Leader": row.leader, Tester: row.tester, "Inception OTP": row.inception, "Inception Payout": row.inceptionPayout ?? 0, "Super X OTP": row.superX, "Super X Payout": row.superXPayout ?? 0, "Total OTP": row.total, "Total Payout": row.totalPayout ?? 0 }))), "Testers");
  XLSX.writeFile(workbook, `AI_Report_${report.date}.xlsx`);
}

function downloadAssistantImage(report: AssistantReport) {
  const canvas = document.createElement("canvas"); const scale = 2; const rowHeight = 38; const headerHeight = 54; canvas.width = 900 * scale; canvas.height = (headerHeight + (report.rows.length + new Set(report.rows.map(row => row.leader)).size + 2) * rowHeight) * scale; const context = canvas.getContext("2d"); if (!context) return; context.scale(scale, scale); context.fillStyle = "#ffffff"; context.fillRect(0, 0, 900, canvas.height / scale); const cols = [0, 430, 585, 745, 900]; context.fillStyle = "#d9e7f3"; context.fillRect(0, 0, 900, headerHeight); context.fillStyle = "#0f172a"; context.font = "700 24px Arial"; context.fillText("Project", 10, 36); context.fillText("Super x", 445, 36); context.fillText("Inception", 595, 36); context.fillText("Total", 780, 36); let y = headerHeight; const leaderNames = Array.from(new Set(report.rows.map(row => row.leader))); for (const leader of leaderNames) { const group = report.rows.filter(row => row.leader === leader); const totals = { superX: group.reduce((sum, row) => sum + row.superX, 0), inception: group.reduce((sum, row) => sum + row.inception, 0), total: group.reduce((sum, row) => sum + row.total, 0) }; context.fillStyle = "#c9e2b4"; context.fillRect(0, y, 900, rowHeight); context.fillStyle = "#111827"; context.font = "700 22px Arial"; context.fillText(leader, 10, y + 26); context.textAlign = "right"; context.fillText(String(totals.superX), cols[2] - 12, y + 26); context.fillText(String(totals.inception), cols[3] - 12, y + 26); context.fillText(String(totals.total), cols[4] - 12, y + 26); context.textAlign = "left"; y += rowHeight; for (const row of group) { context.fillStyle = "#ffffff"; context.fillRect(0, y, 900, rowHeight); context.strokeStyle = "#e2e8f0"; context.beginPath(); context.moveTo(0, y + rowHeight - 1); context.lineTo(900, y + rowHeight - 1); context.stroke(); context.fillStyle = "#111827"; context.font = "400 20px Arial"; context.fillText(row.tester, 10, y + 25); context.textAlign = "right"; context.fillText(String(row.superX), cols[2] - 12, y + 25); context.fillText(String(row.inception), cols[3] - 12, y + 25); context.font = "700 20px Arial"; context.fillText(String(row.total), cols[4] - 12, y + 25); context.textAlign = "left"; y += rowHeight; } } const grand = { superX: report.rows.reduce((sum, row) => sum + row.superX, 0), inception: report.rows.reduce((sum, row) => sum + row.inception, 0), total: report.rows.reduce((sum, row) => sum + row.total, 0) }; context.fillStyle = "#b9cdea"; context.fillRect(0, y, 900, rowHeight); context.fillStyle = "#111827"; context.font = "700 22px Arial"; context.fillText("Grand Total", 10, y + 26); context.textAlign = "right"; context.fillText(String(grand.superX), cols[2] - 12, y + 26); context.fillText(String(grand.inception), cols[3] - 12, y + 26); context.fillText(String(grand.total), cols[4] - 12, y + 26); const link = document.createElement("a"); link.download = `AI_Report_${report.date}.png`; link.href = canvas.toDataURL("image/png"); link.click();
}

function SectionHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex items-end justify-between gap-4"><div><p className="mb-2 text-[11px] font-bold uppercase tracking-[0.22em] text-emerald-600">{eyebrow}</p><h1 className="font-display text-3xl font-semibold tracking-tight text-slate-950">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{description}</p>}</div>{action}</div>;
}

function MetricCard({ label, value, detail, icon: Icon, tone = "default", trend }: { label: string; value: string; detail: string; icon: typeof BarChart3; tone?: "default" | "green" | "amber" | "violet"; trend?: "up" | "down" }) {
  const styles = { default: "bg-white border-slate-200", green: "bg-emerald-50/70 border-emerald-100", amber: "bg-amber-50/70 border-amber-100", violet: "bg-violet-50/70 border-violet-100" }[tone];
  const iconStyle = { default: "bg-slate-100 text-slate-600", green: "bg-emerald-100 text-emerald-700", amber: "bg-amber-100 text-amber-700", violet: "bg-violet-100 text-violet-700" }[tone];
  return <Card className={`stat-card border shadow-none ${styles}`}><CardContent className="p-5"><div className="mb-5 flex items-start justify-between"><div className={`flex h-10 w-10 items-center justify-center rounded-xl ${iconStyle}`}><Icon className="h-5 w-5" /></div>{trend && <span className={`flex items-center gap-1 text-xs font-semibold ${trend === "up" ? "text-emerald-600" : "text-rose-500"}`}>{trend === "up" ? <ArrowUpRight className="h-3.5 w-3.5" /> : <ArrowDownRight className="h-3.5 w-3.5" />}Live</span>}</div><p className="text-xs font-medium text-slate-500">{label}</p><p className="mt-1 font-display text-2xl font-semibold tracking-tight text-slate-950">{value}</p><p className="mt-2 text-xs text-slate-500">{detail}</p></CardContent></Card>;
}

function AuthFrame({ eyebrow, title, description, children }: { eyebrow: string; title: string; description: string; children: React.ReactNode }) {
  return <div className="flex min-h-[calc(100vh-130px)] items-center justify-center"><Card className="w-full max-w-xl overflow-hidden border-slate-200 bg-white shadow-xl"><div className="bg-slate-950 px-8 py-8 text-white"><img src="/manus-storage/dream-telco-logo_561b5517.png" alt="Dream Telco" className="mb-5 h-16 w-16 rounded-2xl bg-black object-contain" /><p className="text-[10px] font-bold uppercase tracking-[0.24em] text-orange-300">{eyebrow}</p><h1 className="mt-3 font-display text-3xl font-semibold tracking-tight">{title}</h1><p className="mt-3 max-w-md text-sm leading-6 text-slate-300">{description}</p></div><CardContent className="p-8">{children}</CardContent></Card></div>;
}

function LoginPage() {
  const [, setLocation] = useLocation();
  const login = trpc.auth.login.useMutation({ onSuccess: result => { toast.success("Welcome back"); window.location.href = result.redirect; }, onError: error => toast.error(error.message) });
  const [identifier, setIdentifier] = useState(""); const [password, setPassword] = useState("");
  return <AuthFrame eyebrow="Secure access" title="Sign in to operations" description="Use your registered email address or international phone number and password."><form className="space-y-5" onSubmit={event => { event.preventDefault(); login.mutate({ identifier, password }); }}><div><Label>Email or phone number</Label><Input className="mt-2 h-11" placeholder="name@example.com or +923001234567" value={identifier} onChange={event => setIdentifier(event.target.value)} /></div><div><Label>Password</Label><Input className="mt-2 h-11" type="password" value={password} onChange={event => setPassword(event.target.value)} /></div><Button disabled={login.isPending} className="h-11 w-full bg-slate-950 hover:bg-slate-800">{login.isPending ? "Signing in…" : "Sign in"}</Button><p className="text-center text-sm text-slate-500">Don&apos;t have an account? <button type="button" onClick={() => setLocation("/register")} className="font-semibold text-emerald-700">Register here</button></p></form></AuthFrame>;
}

function RegisterPage() {
  const [, setLocation] = useLocation();
  const leaders = trpc.roster.list.useQuery();
  const [step, setStep] = useState<"details" | "verification">("details");
  const [registration, setRegistration] = useState<{ userId: number; emailOtp: string; phoneOtp: string } | null>(null);
  const [form, setForm] = useState({ name: "", email: "", phoneNumber: "+92", password: "", confirmPassword: "", role: "tester" as "tester" | "team_leader", teamLeaderId: "" });
  const [emailOtp, setEmailOtp] = useState("");
  const [phoneOtp, setPhoneOtp] = useState("");
  const update = (key: keyof typeof form, value: string) => setForm(current => ({ ...current, [key]: value }));
  const requestOtp = trpc.auth.requestRegistrationOtp.useMutation({ onSuccess: result => { setRegistration(current => current ? { ...current, emailOtp: result.emailOtp, phoneOtp: result.phoneOtp } : null); setStep("verification"); toast.success("Account details saved. Enter both OTPs below."); }, onError: error => toast.error(error.message) });
  const register = trpc.auth.register.useMutation({ onSuccess: result => { setRegistration({ userId: result.userId, emailOtp: "", phoneOtp: "" }); requestOtp.mutate({ userId: result.userId }); }, onError: error => toast.error(error.message) });
  const verify = trpc.auth.verifyRegistrationOtp.useMutation({ onSuccess: result => { toast.success("Registration complete — welcome to Dream Telco"); window.location.href = result.redirect; }, onError: error => toast.error(error.message) });
  const submitDetails = (event: React.FormEvent) => { event.preventDefault(); if (form.password !== form.confirmPassword) { toast.error("Passwords do not match"); return; } register.mutate({ name: form.name, email: form.email, phoneNumber: form.phoneNumber, password: form.password, role: form.role, teamLeaderId: form.role === "tester" ? Number(form.teamLeaderId) : null }); };
  if (step === "verification" && registration) return <AuthFrame eyebrow="Step 2 · Verify in place" title="Complete registration" description="Stay on this page and enter the two six-digit codes. No email app, popup, or external redirect is used."><div className="space-y-5"><div className="rounded-2xl border border-orange-200 bg-orange-50 p-4 text-sm leading-6 text-orange-950"><p className="font-semibold">Sandbox mode is ready</p><p className="mt-1">Use the test code <strong>123456</strong> in both fields.</p><p className="mt-1 text-xs text-orange-800">Email OTP: <strong>{registration.emailOtp || "Generating…"}</strong> · Phone OTP: <strong>{registration.phoneOtp || "Generating…"}</strong></p></div><div><Label>Enter Email OTP</Label><Input autoFocus className="mt-2 h-11 tracking-[0.35em]" inputMode="numeric" maxLength={6} placeholder="123456" value={emailOtp} onChange={event => setEmailOtp(event.target.value.replace(/\D/g, ""))} /></div><div><Label>Enter Phone OTP</Label><Input className="mt-2 h-11 tracking-[0.35em]" inputMode="numeric" maxLength={6} placeholder="123456" value={phoneOtp} onChange={event => setPhoneOtp(event.target.value.replace(/\D/g, ""))} /></div><Button disabled={verify.isPending || emailOtp.length !== 6 || phoneOtp.length !== 6} className="h-11 w-full bg-slate-950 hover:bg-slate-800" onClick={() => verify.mutate({ userId: registration.userId, emailOtp, phoneOtp })}>{verify.isPending ? "Completing registration…" : "Complete Registration"}</Button><button type="button" className="w-full text-center text-sm font-semibold text-slate-500 hover:text-slate-800" onClick={() => setStep("details")}>Back to details</button></div></AuthFrame>;
  return <AuthFrame eyebrow="Step 1 · Create account" title="Join the reporting workspace" description="Enter your details. After you continue, verification appears right here in the browser — no mail client or external account check."><form className="grid gap-5 sm:grid-cols-2" onSubmit={submitDetails}><div className="sm:col-span-2"><Label>Full name</Label><Input className="mt-2 h-11" placeholder="Your full name" value={form.name} onChange={event => update("name", event.target.value)} /></div><div><Label>Email address</Label><Input className="mt-2 h-11" type="email" autoComplete="email" placeholder="name@example.com" value={form.email} onChange={event => update("email", event.target.value)} /></div><div><Label>Mobile / WhatsApp</Label><Input className="mt-2 h-11" autoComplete="tel" placeholder="+923001234567" value={form.phoneNumber} onChange={event => update("phoneNumber", event.target.value)} /></div><div><Label>Password</Label><Input className="mt-2 h-11" type="password" minLength={8} autoComplete="new-password" value={form.password} onChange={event => update("password", event.target.value)} /></div><div><Label>Confirm password</Label><Input className="mt-2 h-11" type="password" minLength={8} autoComplete="new-password" value={form.confirmPassword} onChange={event => update("confirmPassword", event.target.value)} /></div><div className="sm:col-span-2"><Label>Role</Label><Select value={form.role} onValueChange={value => { update("role", value); if (value !== "tester") update("teamLeaderId", ""); }}><SelectTrigger className="mt-2 h-11"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="tester">Tester</SelectItem><SelectItem value="team_leader">Team Leader</SelectItem></SelectContent></Select></div>{form.role === "tester" && <div className="sm:col-span-2"><Label>Team Leader</Label><Select value={form.teamLeaderId} onValueChange={value => update("teamLeaderId", value)}><SelectTrigger className="mt-2 h-11"><SelectValue placeholder="Select an active Team Leader" /></SelectTrigger><SelectContent>{(leaders.data?.leaders ?? []).filter(leader => leader.status === "ACTIVE").map(leader => <SelectItem key={leader.id} value={String(leader.id)}>{leader.name}</SelectItem>)}</SelectContent></Select><p className="mt-1.5 text-[11px] text-slate-400">Choose the Team Leader for this Tester account.</p></div>}<Button type="submit" disabled={register.isPending || requestOtp.isPending || (form.role === "tester" && !form.teamLeaderId)} className="h-11 bg-slate-950 hover:bg-slate-800 sm:col-span-2">{register.isPending || requestOtp.isPending ? "Preparing verification…" : "Continue to Verification"}</Button><p className="text-center text-sm text-slate-500 sm:col-span-2">Already have an account? <button type="button" onClick={() => setLocation("/login")} className="font-semibold text-emerald-700">Sign in</button></p></form></AuthFrame>;
}

function VerifyPage() {
  const [, setLocation] = useLocation();
  return <AuthFrame eyebrow="Verification" title="Use the registration form" description="Verification is now completed in place. Return to registration to begin a new two-step signup."><Button className="h-11 w-full bg-slate-950" onClick={() => setLocation("/register")}>Return to registration</Button></AuthFrame>;
}

function Overview({ go }: { go: (path: string) => void }) {
  const [date, setDate] = useState(today);
  const overview = trpc.dashboard.overview.useQuery({ date });
  const data = overview.data;
  const leaders = data?.leaders ?? [];
  const total = data?.totals?.total ?? 0;
  const maxLeader = Math.max(...leaders.map(item => item.total), 1);
  return <div className="space-y-8"><SectionHeading eyebrow="Command center" title="Good morning, Category Leader." description={`Your reporting workspace is ready. Review ${new Date(date).toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" })}'s activity and resolve the items that need attention.`} action={<div className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white p-1.5 shadow-sm"><Label htmlFor="overview-date" className="sr-only">Report date</Label><Input id="overview-date" type="date" value={date} onChange={event => setDate(event.target.value)} className="h-8 w-[145px] border-0 bg-transparent px-2 text-xs shadow-none focus-visible:ring-0" /><Button size="sm" className="h-8 bg-slate-950 px-3 text-xs hover:bg-slate-800" onClick={() => overview.refetch()}>Refresh</Button></div>} />
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Overall performance" value={formatNumber(total)} detail={`${formatNumber(data?.totals?.reportingTesters ?? 0)} testers reporting`} icon={BarChart3} tone="green" trend="up" /><MetricCard label="Super X" value={formatNumber(data?.totals?.superX ?? 0)} detail="Project output today" icon={Target} /><MetricCard label="Inception" value={formatNumber(data?.totals?.inception ?? 0)} detail="Project output today" icon={Sparkles} tone="violet" /><MetricCard label="Payout exceptions" value={String(data?.payoutTotals?.exceptions ?? 0)} detail="Needs verification" icon={AlertTriangle} tone="amber" /></div>
    <div className="grid gap-6 xl:grid-cols-[1.5fr_1fr]"><Card className="border-slate-200 shadow-none"><CardHeader className="flex-row items-center justify-between space-y-0 border-b border-slate-100 px-6 py-5"><div><CardTitle className="text-base">Team performance</CardTitle><p className="mt-1 text-xs text-slate-500">Actual output by Team Leader</p></div><Button variant="outline" className="h-8 gap-1.5 border-slate-200 bg-white text-xs" onClick={() => go("/daily")}>View report <ChevronRight className="h-3.5 w-3.5" /></Button></CardHeader><CardContent className="p-6">{overview.isLoading ? <div className="flex h-56 items-center justify-center"><Loader2 className="h-5 w-5 animate-spin text-emerald-600" /></div> : <div className="space-y-5">{leaders.map((leader, index) => <div key={leader.leaderId} className="group"><div className="mb-2 flex items-center justify-between text-sm"><div className="flex items-center gap-3"><span className="flex h-7 w-7 items-center justify-center rounded-full bg-slate-100 text-[11px] font-bold text-slate-600">{index + 1}</span><span className="font-medium text-slate-800">{leader.leader}</span><span className="text-xs text-slate-400">{leader.reporting}/{leader.activeTesters} reporting</span></div><span className="font-semibold text-slate-900">{formatNumber(leader.total)}</span></div><div className="h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-gradient-to-r from-emerald-500 to-teal-400 transition-all" style={{ width: `${Math.max(4, (leader.total / maxLeader) * 100)}%` }} /></div><div className="mt-2 flex gap-4 text-[11px] text-slate-400"><span>Super X {formatNumber(leader.superX)}</span><span>Inception {formatNumber(leader.inception)}</span><span>{leader.zero} zero activity</span></div></div>)}{!leaders.length && <div className="flex h-56 items-center justify-center text-sm text-slate-400">No active Team Leaders yet.</div>}</div>}</CardContent></Card>
      <Card className="border-slate-200 shadow-none"><CardHeader className="border-b border-slate-100 px-6 py-5"><CardTitle className="text-base">Top performers</CardTitle><p className="mt-1 text-xs text-slate-500">Highest output on the selected date</p></CardHeader><CardContent className="p-6"><div className="space-y-4">{(data?.topTesters ?? []).slice(0, 6).map((tester, index) => <div key={tester.name} className="flex items-center justify-between"><div className="flex items-center gap-3"><div className={`flex h-8 w-8 items-center justify-center rounded-full text-xs font-bold ${index === 0 ? "bg-amber-100 text-amber-700" : "bg-slate-100 text-slate-600"}`}>{index + 1}</div><div><p className="text-sm font-medium text-slate-800">{tester.name}</p><p className="text-[11px] text-slate-400">Tester performance</p></div></div><span className="text-sm font-semibold text-slate-900">{formatNumber(tester.total)}</span></div>)}{!(data?.topTesters?.length) && <div className="py-16 text-center text-sm text-slate-400">Performance will appear here once daily data is entered.</div>}</div><Button variant="outline" className="mt-6 h-9 w-full border-slate-200 bg-white text-xs" onClick={() => go("/daily")}>Open daily report</Button></CardContent></Card></div>
    <div className="grid gap-4 sm:grid-cols-3"><button onClick={() => go("/daily")} className="quick-action"><FileSpreadsheet className="h-5 w-5 text-emerald-600" /><span><b>Enter daily data</b><small>Add tester output by project</small></span><ChevronRight className="ml-auto h-4 w-4 text-slate-400" /></button><button onClick={() => go("/payouts")} className="quick-action"><WalletCards className="h-5 w-5 text-violet-600" /><span><b>Process payouts</b><small>Import and separate tester payouts</small></span><ChevronRight className="ml-auto h-4 w-4 text-slate-400" /></button><button onClick={() => go("/assistant")} className="quick-action"><Sparkles className="h-5 w-5 text-amber-600" /><span><b>Ask the assistant</b><small>Find insights in plain language</small></span><ChevronRight className="ml-auto h-4 w-4 text-slate-400" /></button></div>
  </div>;
}

function DailyReport() {
  const [date, setDate] = useState(today); const [testerId, setTesterId] = useState(""); const [projectId, setProjectId] = useState(""); const [quantity, setQuantity] = useState("");
  const overview = trpc.dashboard.overview.useQuery({ date }); const mutation = trpc.performance.create.useMutation({ onSuccess: () => { toast.success("Performance record saved"); setQuantity(""); overview.refetch(); }, onError: error => toast.error(error.message) });
  const data = overview.data; const projectMap = useMemo(() => new Map((data?.projects ?? []).map(project => [String(project.id), project.name])), [data?.projects]); const leaderMap = useMemo(() => new Map((data?.leaders ?? []).map(leader => [leader.leaderId, leader.leader])), [data?.leaders]);
  const exportReport = () => downloadStyledDailyWorkbook(data, date);
  return <div className="space-y-8"><SectionHeading eyebrow="Daily reporting" title="Performance ledger" description="Enter and validate tester output without changing historical records. Every record keeps its date, team assignment, and source." action={<Button className="gap-2 bg-slate-950 hover:bg-slate-800" onClick={exportReport}><FileSpreadsheet className="h-4 w-4" />Export report</Button>} /><div className="grid gap-6 xl:grid-cols-[360px_1fr]"><Card className="h-fit border-slate-200 shadow-none"><CardHeader><CardTitle className="text-base">Add performance</CardTitle><p className="text-xs text-slate-500">One entry per tester and project</p></CardHeader><CardContent className="space-y-4"><div><Label className="text-xs">Business date</Label><Input type="date" value={date} onChange={event => setDate(event.target.value)} className="mt-1.5" /></div><div><Label className="text-xs">Tester</Label><Select value={testerId} onValueChange={setTesterId}><SelectTrigger className="mt-1.5"><SelectValue placeholder="Choose a tester" /></SelectTrigger><SelectContent>{(data?.testers ?? []).filter(t => t.status === "ACTIVE").map(tester => <SelectItem key={tester.id} value={String(tester.id)}>{tester.name}</SelectItem>)}</SelectContent></Select></div><div><Label className="text-xs">Project</Label><Select value={projectId} onValueChange={setProjectId}><SelectTrigger className="mt-1.5"><SelectValue placeholder="Choose a project" /></SelectTrigger><SelectContent>{(data?.projects ?? []).filter(p => p.status === "ACTIVE").map(project => <SelectItem key={project.id} value={String(project.id)}>{project.name}</SelectItem>)}</SelectContent></Select></div><div><Label className="text-xs">Quantity</Label><Input type="number" min="0" value={quantity} onChange={event => setQuantity(event.target.value)} placeholder="0" className="mt-1.5" /></div><Button className="mt-2 w-full gap-2 bg-emerald-600 hover:bg-emerald-700" disabled={!testerId || !projectId || !quantity || mutation.isPending} onClick={() => mutation.mutate({ businessDate: date, testerId: Number(testerId), projectId: Number(projectId), quantity: Number(quantity), source: "Manual entry" })}>{mutation.isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />}Save record</Button><p className="text-[11px] leading-5 text-slate-400">Target: Not provided. Add a target in the Targets section before calculating achievement.</p></CardContent></Card><Card className="border-slate-200 shadow-none"><CardHeader className="flex-row items-center justify-between space-y-0"><div><CardTitle className="text-base">Tester performance</CardTitle><p className="text-xs text-slate-500">{new Date(`${date}T00:00:00`).toLocaleDateString()} · {data?.performance?.length ?? 0} records</p></div><div className="flex items-center gap-2"><Badge variant="outline" className="gap-1 border-slate-200 text-xs"><Filter className="h-3 w-3" />All projects</Badge><Badge className="bg-emerald-50 text-emerald-700 hover:bg-emerald-50">Live totals</Badge></div></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-y border-slate-100 bg-slate-50/70 text-[11px] uppercase tracking-wider text-slate-400"><tr><th className="px-6 py-3 font-semibold">Tester</th><th className="px-6 py-3 font-semibold">Team Leader</th><th className="px-6 py-3 font-semibold">Project</th><th className="px-6 py-3 text-right font-semibold">Quantity</th><th className="px-6 py-3 font-semibold">Source</th></tr></thead><tbody className="divide-y divide-slate-100">{(data?.performance ?? []).map(row => <tr key={row.id} className="hover:bg-slate-50/70"><td className="px-6 py-3.5 font-medium text-slate-800">{data?.testers?.find(t => t.id === row.testerId)?.name ?? "Unknown"}</td><td className="px-6 py-3.5 text-slate-500">{leaderMap.get(row.teamLeaderId) ?? "Unassigned"}</td><td className="px-6 py-3.5 text-slate-500">{projectMap.get(String(row.projectId)) ?? "Unknown"}</td><td className="px-6 py-3.5 text-right font-semibold text-slate-900">{formatNumber(Number(row.quantity))}</td><td className="px-6 py-3.5 text-xs text-slate-400">{row.source ?? "Not provided"}</td></tr>)}{!(data?.performance?.length) && <tr><td colSpan={5} className="px-6 py-20 text-center text-sm text-slate-400">No records for this date. Use the form to add the first validated entry.</td></tr>}</tbody></table></div></CardContent></Card></div></div>;
}

function Payouts() {
  const [rawText, setRawText] = useState("RK, 5000\nRida, 3000\nUnknown Person, 2500"); const [fileName, setFileName] = useState("Payout_import.txt"); const [result, setResult] = useState<{ records: number; matched: number; exceptions: number } | null>(null); const mutation = trpc.payouts.importText.useMutation({ onSuccess: value => { setResult(value); toast.success("Payout file processed"); }, onError: error => toast.error(error.message) }); const payouts = trpc.payouts.list.useQuery(); const rows = payouts.data ?? [];
  const exportPayouts = () => { downloadWorkbook({ "Payout Summary": [{ "Total records": rows.length, "Matched records": rows.filter(row => row.status === "MATCHED").length, Exceptions: rows.filter(row => row.status !== "MATCHED").length, "Total net payout": rows.reduce((sum, row) => sum + Number(row.netPayout), 0) }], "Tester Payout": rows.map(row => ({ Tester: row.testerNameRaw, Project: row.projectNameRaw ?? "Not provided", "Payout Date": new Date(row.payoutDate).toLocaleDateString(), "Gross Payout": Number(row.grossPayout), Deductions: Number(row.deductions), "Net Payout": Number(row.netPayout), Status: row.status, "Source File": row.sourceFile ?? "Not provided" })), Exceptions: rows.filter(row => row.status !== "MATCHED").map(row => ({ Tester: row.testerNameRaw, Status: row.status, Notes: row.notes ?? "Not provided", "Source File": row.sourceFile ?? "Not provided" })), "Raw Data": rows.map(row => ({ ID: row.id, RawTester: row.testerNameRaw, RawProject: row.projectNameRaw ?? "", Gross: Number(row.grossPayout), Deductions: Number(row.deductions), Net: Number(row.netPayout), Status: row.status })) }, `Payout_Report_${today}.xlsx`); toast.success("Payout workbook downloaded"); };
  const handleFile = async (file: File) => { setFileName(file.name); const buffer = await file.arrayBuffer(); try { const workbook = XLSX.read(buffer, { type: "array" }); const firstSheet = workbook.Sheets[workbook.SheetNames[0] ?? ""]; const rows = XLSX.utils.sheet_to_json<unknown[]>(firstSheet, { header: 1 }); setRawText(rows.map(row => row.map(value => String(value ?? "")).join(", ")).join("\n")); toast.success("Spreadsheet loaded for validation"); } catch { const text = await file.text(); setRawText(text); } };
  return <div className="space-y-8"><SectionHeading eyebrow="Payout operations" title="Payout control room" description="Import raw payout text, match it against the master roster, and keep every exception visible for human review." action={<Button variant="outline" className="gap-2 border-slate-200 bg-white" onClick={exportPayouts}><FileSpreadsheet className="h-4 w-4" />Generate workbook</Button>} /><div className="grid gap-6 xl:grid-cols-[390px_1fr]"><Card className="border-slate-200 shadow-none"><CardHeader><CardTitle className="text-base">Process a payout source</CardTitle><p className="text-xs text-slate-500">Paste a CSV, spreadsheet extract, or WhatsApp-style rows</p></CardHeader><CardContent className="space-y-4"><label className="flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-dashed border-slate-300 bg-slate-50 px-4 py-3 text-xs font-medium text-slate-600 hover:border-violet-300 hover:bg-violet-50"><Upload className="h-4 w-4 text-violet-600" />Choose XLSX / CSV / TXT<input type="file" accept=".xlsx,.xls,.csv,.txt" className="hidden" onChange={event => { const file = event.target.files?.[0]; if (file) void handleFile(file); }} /></label><div><Label className="text-xs">Source file name</Label><Input value={fileName} onChange={event => setFileName(event.target.value)} className="mt-1.5" /></div><div><Label className="text-xs">Raw payout data</Label><Textarea value={rawText} onChange={event => setRawText(event.target.value)} className="mt-1.5 min-h-[180px] font-mono text-xs leading-6" /></div><Button className="w-full gap-2 bg-violet-600 hover:bg-violet-700" disabled={!rawText.trim() || mutation.isPending} onClick={() => mutation.mutate({ fileName, rawText })}>{mutation.isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Upload className="h-4 w-4" />}Process source</Button>{result && <div className="rounded-xl border border-emerald-100 bg-emerald-50 p-4 text-xs text-emerald-800"><p className="font-semibold">Import complete</p><p className="mt-1">{result.records} records · {result.matched} matched · {result.exceptions} exceptions</p></div>}<div className="rounded-xl border border-amber-100 bg-amber-50 p-4 text-xs leading-5 text-amber-800"><p className="font-semibold">Validation policy</p><p className="mt-1">Possible matches, unknown testers, missing amounts, duplicates, and conflicts are never auto-removed.</p></div></CardContent></Card><Card className="border-slate-200 shadow-none"><CardHeader className="flex-row items-center justify-between space-y-0"><div><CardTitle className="text-base">Recent payout records</CardTitle><p className="text-xs text-slate-500">Matched and exception records from all imported sources</p></div><Badge variant="outline" className="border-slate-200">{rows.length} records</Badge></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-y border-slate-100 bg-slate-50/70 text-[11px] uppercase tracking-wider text-slate-400"><tr><th className="px-6 py-3 font-semibold">Tester</th><th className="px-6 py-3 font-semibold">Project</th><th className="px-6 py-3 text-right font-semibold">Net payout</th><th className="px-6 py-3 font-semibold">Status</th><th className="px-6 py-3 font-semibold">Source</th></tr></thead><tbody className="divide-y divide-slate-100">{rows.slice(0, 12).map(row => <tr key={row.id}><td className="px-6 py-3.5 font-medium text-slate-800">{row.testerNameRaw}</td><td className="px-6 py-3.5 text-slate-500">{row.projectNameRaw || "Not provided"}</td><td className="px-6 py-3.5 text-right font-semibold text-slate-900">{formatMoney(Number(row.netPayout))}</td><td className="px-6 py-3.5"><StatusBadge status={row.status} /></td><td className="px-6 py-3.5 text-xs text-slate-400">{row.sourceFile || "Not provided"}</td></tr>)}{!rows.length && <tr><td colSpan={5} className="px-6 py-20 text-center text-sm text-slate-400">No payout records yet. Process a source to create a traceable payout ledger.</td></tr>}</tbody></table></div></CardContent></Card></div></div>;
}

function StatusBadge({ status }: { status: string }) { const good = status === "MATCHED" || status === "PROCESSED"; const warn = status === "POSSIBLE_MATCH" || status === "PARTIAL"; return <Badge className={good ? "bg-emerald-50 text-emerald-700 hover:bg-emerald-50" : warn ? "bg-amber-50 text-amber-700 hover:bg-amber-50" : "bg-rose-50 text-rose-700 hover:bg-rose-50"}>{status.replaceAll("_", " ")}</Badge>; }

function Roster() {
  const [newLeader, setNewLeader] = useState(""); const [newTester, setNewTester] = useState(""); const [selectedLeader, setSelectedLeader] = useState(""); const roster = trpc.roster.list.useQuery(); const utils = trpc.useUtils(); const addLeader = trpc.roster.addLeader.useMutation({ onSuccess: () => { setNewLeader(""); utils.roster.list.invalidate(); toast.success("Team Leader added"); }, onError: error => toast.error(error.message) }); const addTester = trpc.roster.addTester.useMutation({ onSuccess: () => { setNewTester(""); utils.roster.list.invalidate(); toast.success("Tester added"); }, onError: error => toast.error(error.message) }); const toggle = trpc.roster.toggleTester.useMutation({ onSuccess: () => { utils.roster.list.invalidate(); toast.success("Tester status updated"); } }); const deleteTester = trpc.roster.deleteTester.useMutation({ onSuccess: () => { utils.roster.list.invalidate(); toast.success("Tester and linked data deleted"); }, onError: error => toast.error(error.message) }); const deleteLeader = trpc.roster.deleteLeader.useMutation({ onSuccess: () => { utils.roster.list.invalidate(); toast.success("Team Leader and linked data deleted"); }, onError: error => toast.error(error.message) }); const leaders = roster.data?.leaders ?? []; const testers = roster.data?.testers ?? [];
  return <div className="space-y-8"><SectionHeading eyebrow="Master data" title="Roster & teams" description="Keep the hierarchy clean. Deactivate instead of deleting so historical assignments remain intact." action={<div className="flex items-center gap-2 rounded-xl bg-emerald-50 px-3 py-2 text-xs font-medium text-emerald-700"><Check className="h-3.5 w-3.5" />Source of truth</div>} /><div className="grid gap-6 xl:grid-cols-[360px_1fr]"><Card className="h-fit border-slate-200 shadow-none"><CardHeader><CardTitle className="text-base">Add to roster</CardTitle><p className="text-xs text-slate-500">Normal additions do not need confirmation</p></CardHeader><CardContent className="space-y-5"><div className="space-y-2"><Label className="text-xs">New Team Leader</Label><div className="flex gap-2"><Input value={newLeader} onChange={event => setNewLeader(event.target.value)} placeholder="e.g. Hamza" /><Button size="icon" className="shrink-0 bg-slate-950" disabled={!newLeader.trim() || addLeader.isPending} onClick={() => addLeader.mutate({ name: newLeader })}><Plus className="h-4 w-4" /></Button></div></div><div className="space-y-2"><Label className="text-xs">New tester</Label><Input value={newTester} onChange={event => setNewTester(event.target.value)} placeholder="Tester name" /><Select value={selectedLeader} onValueChange={setSelectedLeader}><SelectTrigger className="mt-2"><SelectValue placeholder="Assign under Team Leader" /></SelectTrigger><SelectContent>{leaders.filter(l => l.status === "ACTIVE").map(leader => <SelectItem key={leader.id} value={String(leader.id)}>{leader.name}</SelectItem>)}</SelectContent></Select><Button className="mt-2 w-full bg-emerald-600 hover:bg-emerald-700" disabled={!newTester.trim() || !selectedLeader || addTester.isPending} onClick={() => addTester.mutate({ name: newTester, teamLeaderId: Number(selectedLeader) })}>Add tester</Button></div><div className="rounded-xl bg-slate-50 p-4 text-xs leading-5 text-slate-500"><b className="text-slate-700">Controlled matching</b><br />Near-duplicate names are flagged for confirmation; they are never auto-merged.</div></CardContent></Card><Card className="border-slate-200 shadow-none"><CardHeader><CardTitle className="text-base">Active hierarchy</CardTitle><p className="text-xs text-slate-500">{leaders.filter(l => l.status === "ACTIVE").length} Team Leaders · {testers.filter(t => t.status === "ACTIVE").length} active testers</p></CardHeader><CardContent className="space-y-3">{leaders.map(leader => <div key={leader.id} className="rounded-xl border border-slate-100 bg-slate-50/50"><div className="flex items-center justify-between px-4 py-3"><div className="flex items-center gap-3"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-slate-900 text-xs font-bold text-white">{leader.name.slice(0, 1)}</div><div><p className="text-sm font-semibold text-slate-800">{leader.name}</p><p className="text-[11px] text-slate-400">{testers.filter(t => t.teamLeaderId === leader.id && t.status === "ACTIVE").length} active testers</p></div></div><div className="flex items-center gap-2"><StatusBadge status={leader.status} /><button aria-label={`Delete ${leader.name}`} className="rounded-md p-1 text-slate-400 hover:bg-rose-50 hover:text-rose-600" onClick={() => deleteLeader.mutate({ teamLeaderId: leader.id })}><Trash2 className="h-3.5 w-3.5" /></button></div></div><div className="grid gap-2 border-t border-slate-100 px-4 py-3 sm:grid-cols-2 lg:grid-cols-3">{testers.filter(t => t.teamLeaderId === leader.id).map(tester => <div key={tester.id} className={`flex items-center justify-between rounded-lg bg-white px-3 py-2 text-xs ${tester.status === "INACTIVE" ? "opacity-50" : ""}`}><span className="font-medium text-slate-700">{tester.name}</span><div className="flex items-center gap-2"><button className="text-[10px] text-slate-400 hover:text-emerald-600" onClick={() => toggle.mutate({ testerId: tester.id, status: tester.status === "ACTIVE" ? "INACTIVE" : "ACTIVE" })}>{tester.status === "ACTIVE" ? "Deactivate" : "Reactivate"}</button><button aria-label={`Delete ${tester.name}`} className="text-slate-300 hover:text-rose-600" onClick={() => deleteTester.mutate({ testerId: tester.id })}><Trash2 className="h-3 w-3" /></button></div></div>)}</div></div>)}</CardContent></Card></div></div>;
}

function Targets() { const [target, setTarget] = useState(""); const [level, setLevel] = useState("DAILY"); const mutation = trpc.targets.create.useMutation({ onSuccess: () => { setTarget(""); toast.success("Target saved"); }, onError: error => toast.error(error.message) }); const targets = trpc.targets.list.useQuery(); return <div className="space-y-8"><SectionHeading eyebrow="Target management" title="Targets & achievement" description="Targets are explicit inputs. When one is missing, the report shows Target Not Provided instead of guessing." /><div className="grid gap-6 xl:grid-cols-[360px_1fr]"><Card className="h-fit border-slate-200 shadow-none"><CardHeader><CardTitle className="text-base">Create a target</CardTitle><p className="text-xs text-slate-500">Start with a level-wide target</p></CardHeader><CardContent className="space-y-4"><div><Label className="text-xs">Target level</Label><Select value={level} onValueChange={setLevel}><SelectTrigger className="mt-1.5"><SelectValue /></SelectTrigger><SelectContent>{["DAILY", "WEEKLY", "MONTHLY", "TEAM_LEADER", "TESTER", "PROJECT"].map(value => <SelectItem key={value} value={value}>{value.replace("_", " ")}</SelectItem>)}</SelectContent></Select></div><div><Label className="text-xs">Target quantity</Label><Input type="number" min="0" value={target} onChange={event => setTarget(event.target.value)} placeholder="e.g. 5000" className="mt-1.5" /></div><Button className="w-full bg-emerald-600 hover:bg-emerald-700" disabled={!target || mutation.isPending} onClick={() => mutation.mutate({ target: Number(target), level: level as "DAILY" | "WEEKLY" | "MONTHLY" | "TEAM_LEADER" | "TESTER" | "PROJECT", effectiveDate: today })}>Save target</Button></CardContent></Card><Card className="border-slate-200 shadow-none"><CardHeader><CardTitle className="text-base">Active targets</CardTitle><p className="text-xs text-slate-500">Achievement = Actual ÷ Target × 100</p></CardHeader><CardContent className="p-0"><table className="w-full text-left text-sm"><thead className="border-y border-slate-100 bg-slate-50/70 text-[11px] uppercase tracking-wider text-slate-400"><tr><th className="px-6 py-3 font-semibold">Level</th><th className="px-6 py-3 font-semibold">Effective date</th><th className="px-6 py-3 text-right font-semibold">Target</th><th className="px-6 py-3 font-semibold">Status</th></tr></thead><tbody className="divide-y divide-slate-100">{(targets.data ?? []).map(row => <tr key={row.id}><td className="px-6 py-4 font-medium text-slate-800">{row.level.replace("_", " ")}</td><td className="px-6 py-4 text-slate-500">{new Date(row.effectiveDate).toLocaleDateString()}</td><td className="px-6 py-4 text-right font-semibold text-slate-900">{formatNumber(Number(row.target))}</td><td className="px-6 py-4"><StatusBadge status="ACTIVE" /></td></tr>)}{!(targets.data?.length) && <tr><td colSpan={4} className="px-6 py-20 text-center text-sm text-slate-400">Target Not Provided</td></tr>}</tbody></table></CardContent></Card></div></div>; }

function Audit() { const logs = trpc.audit.list.useQuery(); return <div className="space-y-8"><SectionHeading eyebrow="Governance" title="Audit trail" description="Every meaningful change is recorded with the action, old value, new value, and reason." /><Card className="border-slate-200 shadow-none"><CardContent className="p-0"><div className="divide-y divide-slate-100">{(logs.data ?? []).map(log => <div key={log.id} className="flex items-start gap-4 px-6 py-4"><div className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-slate-100"><ReceiptText className="h-4 w-4 text-slate-500" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-semibold text-slate-800">{log.action}</p><Badge variant="outline" className="border-slate-200 text-[10px]">logged</Badge></div><p className="mt-1 text-xs text-slate-500">{log.reason || log.userCommand || "System change"}</p></div><time className="shrink-0 text-xs text-slate-400">{new Date(log.createdAt).toLocaleString()}</time></div>)}{!(logs.data?.length) && <div className="py-24 text-center text-sm text-slate-400">No changes have been logged yet.</div>}</div></CardContent></Card></div>; }

function AdminDashboard() {
  const admin = trpc.adminDashboard.summary.useQuery();
  const utils = trpc.useUtils();
  const sendTestReport = trpc.adminDashboard.sendTestReport.useMutation({ onSuccess: result => toast.success(`Test report dispatched via ${result.delivery.channel}`), onError: error => toast.error(error.message) });
  const approve = trpc.adminDashboard.approveUser.useMutation({ onSuccess: () => { utils.adminDashboard.summary.invalidate(); utils.userManagement.directory.invalidate(); toast.success("User approved"); }, onError: error => toast.error(error.message) });
  const status = trpc.userManagement.updateStatus.useMutation({ onSuccess: () => { utils.adminDashboard.summary.invalidate(); utils.userManagement.directory.invalidate(); toast.success("Account status updated"); }, onError: error => toast.error(error.message) });
  const review = trpc.adminDashboard.reviewPayout.useMutation({ onSuccess: () => { utils.adminDashboard.summary.invalidate(); utils.payouts.list.invalidate(); toast.success("Payout review updated"); }, onError: error => toast.error(error.message) });
  const data = admin.data; const metrics = data?.metrics;
  return <div className="space-y-8"><SectionHeading eyebrow="Administration" title="Admin dashboard" description="Approve new accounts, protect the workspace, and move payout records through a traceable review lifecycle." action={<div className="flex items-center gap-2"><Button variant="outline" className="gap-2 border-slate-200 bg-white text-xs" disabled={sendTestReport.isPending} onClick={() => sendTestReport.mutate()}><FileSpreadsheet className="h-3.5 w-3.5" />{sendTestReport.isPending ? "Preparing…" : "Send test report now"}</Button><Badge className="gap-2 border-emerald-200 bg-emerald-50 text-emerald-700"><ShieldCheck className="h-3.5 w-3.5" />Root admin controls</Badge></div>} />
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div className="admin-metric"><Users className="h-5 w-5 text-emerald-600" /><p className="mt-4 text-xs text-slate-500">Total users</p><p className="mt-1 text-2xl font-semibold text-slate-950">{metrics?.totalUsers ?? 0}</p><span>{metrics?.activeUsers ?? 0} active</span></div><div className="admin-metric"><UserCheck className="h-5 w-5 text-amber-600" /><p className="mt-4 text-xs text-slate-500">Pending approval</p><p className="mt-1 text-2xl font-semibold text-slate-950">{metrics?.pendingUsers ?? 0}</p><span>Needs review</span></div><div className="admin-metric"><CreditCard className="h-5 w-5 text-violet-600" /><p className="mt-4 text-xs text-slate-500">Payout value</p><p className="mt-1 text-2xl font-semibold text-slate-950">{formatMoney(metrics?.payoutValue ?? 0)}</p><span>{metrics?.pendingPayouts ?? 0} pending review</span></div><div className="admin-metric"><Ban className="h-5 w-5 text-rose-600" /><p className="mt-4 text-xs text-slate-500">Blocked accounts</p><p className="mt-1 text-2xl font-semibold text-slate-950">{metrics?.blockedUsers ?? 0}</p><span>Access disabled</span></div></div>
    <Card className="border-slate-200 shadow-none"><CardHeader className="flex-row items-center justify-between space-y-0"><div><CardTitle className="text-base">User directory</CardTitle><p className="mt-1 text-xs text-slate-500">Approve verified registrations, block suspicious accounts, and keep roles visible.</p></div><Badge variant="outline" className="border-slate-200">{data?.users.length ?? 0} accounts</Badge></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[980px] text-left text-sm"><thead className="border-y border-slate-100 bg-slate-50/70 text-[11px] uppercase tracking-wider text-slate-400"><tr><th className="px-6 py-3">User</th><th className="px-4 py-3">Contact</th><th className="px-4 py-3">Role</th><th className="px-4 py-3">Verification</th><th className="px-4 py-3">Status</th><th className="px-6 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-100">{(data?.users ?? []).map(row => <tr key={row.id} className="hover:bg-slate-50/70"><td className="px-6 py-4"><p className="font-semibold text-slate-800">{row.name || "Unnamed user"}</p><p className="mt-1 text-[11px] text-slate-400">Joined {new Date(row.createdAt).toLocaleDateString()}</p></td><td className="px-4 py-4 text-xs text-slate-600"><p>{row.email || "No email"}</p><p className="mt-1 text-slate-400">{row.phoneNumber || "No phone"}</p></td><td className="px-4 py-4"><Badge variant="outline" className="border-slate-200">{row.accountRole.replace("_", " ")}</Badge></td><td className="px-4 py-4 text-xs">{row.emailVerified && row.phoneVerified ? <span className="font-medium text-emerald-700">Email + phone verified</span> : <span className="text-amber-700">Verification pending</span>}</td><td className="px-4 py-4"><StatusBadge status={row.accountStatus === "active" ? "ACTIVE" : row.accountStatus === "blocked" ? "BLOCKED" : "PENDING"} /></td><td className="px-6 py-4"><div className="flex justify-end gap-2">{row.accountStatus === "pending" && <Button size="sm" className="h-8 gap-1.5 bg-emerald-600 text-xs hover:bg-emerald-700" disabled={approve.isPending} onClick={() => approve.mutate({ userId: row.id })}><UserCheck className="h-3.5 w-3.5" />Approve</Button>}{row.id !== admin.data?.users.find(user => user.accountRole === "admin")?.id && <Button size="sm" variant="outline" className="h-8 gap-1.5 border-slate-200 bg-white text-xs" disabled={status.isPending} onClick={() => status.mutate({ userId: row.id, status: row.accountStatus === "blocked" ? "active" : "blocked", isVerified: row.accountStatus === "blocked" ? 1 : 0 })}>{row.accountStatus === "blocked" ? <><ShieldCheck className="h-3.5 w-3.5" />Unblock</> : <><Ban className="h-3.5 w-3.5" />Block</>}</Button>}</div></td></tr>)}{!data?.users.length && <tr><td colSpan={6} className="px-6 py-16 text-center text-sm text-slate-400">No registered users yet.</td></tr>}</tbody></table></div></CardContent></Card>
    <Card className="border-slate-200 shadow-none"><CardHeader className="flex-row items-center justify-between space-y-0"><div><CardTitle className="text-base">Payout management</CardTitle><p className="mt-1 text-xs text-slate-500">Review matched records, reject exceptions, and mark completed transfers as paid.</p></div><div className="flex gap-2"><Badge variant="outline" className="border-amber-200 text-amber-700">{metrics?.pendingPayouts ?? 0} pending</Badge><Badge variant="outline" className="border-emerald-200 text-emerald-700">{metrics?.paidPayouts ?? 0} paid</Badge></div></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left text-sm"><thead className="border-y border-slate-100 bg-slate-50/70 text-[11px] uppercase tracking-wider text-slate-400"><tr><th className="px-6 py-3">Tester / source</th><th className="px-4 py-3">Project</th><th className="px-4 py-3 text-right">Net payout</th><th className="px-4 py-3">Match</th><th className="px-4 py-3">Review state</th><th className="px-6 py-3 text-right">Manage</th></tr></thead><tbody className="divide-y divide-slate-100">{(data?.payouts ?? []).slice(0, 25).map(row => <tr key={row.id} className="hover:bg-slate-50/70"><td className="px-6 py-3.5"><p className="font-medium text-slate-800">{row.testerNameRaw}</p><p className="text-[11px] text-slate-400">{row.sourceFile || "Manual record"}</p></td><td className="px-4 py-3.5 text-slate-500">{row.projectNameRaw || "Not provided"}</td><td className="px-4 py-3.5 text-right font-semibold text-slate-900">{formatMoney(Number(row.netPayout))}</td><td className="px-4 py-3.5"><StatusBadge status={row.status} /></td><td className="px-4 py-3.5"><StatusBadge status={row.reviewStatus} /></td><td className="px-6 py-3.5"><div className="flex justify-end gap-2">{row.reviewStatus === "PENDING" && <><Button size="sm" className="h-8 bg-emerald-600 text-xs hover:bg-emerald-700" disabled={review.isPending || row.status !== "MATCHED"} onClick={() => review.mutate({ payoutId: row.id, reviewStatus: "APPROVED" })}>Approve</Button><Button size="sm" variant="outline" className="h-8 border-rose-200 bg-white text-xs text-rose-700" disabled={review.isPending} onClick={() => review.mutate({ payoutId: row.id, reviewStatus: "REJECTED" })}>Reject</Button></>}{row.reviewStatus === "APPROVED" && <Button size="sm" className="h-8 bg-violet-600 text-xs hover:bg-violet-700" disabled={review.isPending} onClick={() => review.mutate({ payoutId: row.id, reviewStatus: "PAID" })}>Mark paid</Button>}</div></td></tr>)}{!data?.payouts.length && <tr><td colSpan={6} className="px-6 py-16 text-center text-sm text-slate-400">No payout records require review.</td></tr>}</tbody></table></div></CardContent></Card>
  </div>;
}

function UserDirectory() {
  const { user } = useAuth();
  const utils = trpc.useUtils();
  const directory = trpc.userManagement.directory.useQuery(undefined, { enabled: user?.role === "admin" });
  const roster = trpc.roster.list.useQuery(undefined, { enabled: user?.role === "admin" });
  const statusMutation = trpc.userManagement.updateStatus.useMutation({ onSuccess: () => { toast.success("Account status updated"); utils.userManagement.directory.invalidate(); }, onError: error => toast.error(error.message) });
  const roleMutation = trpc.userManagement.updateRole.useMutation({ onSuccess: () => { toast.success("Role assignment updated"); utils.userManagement.directory.invalidate(); }, onError: error => toast.error(error.message) });
  const deleteMutation = trpc.userManagement.delete.useMutation({ onSuccess: () => { toast.success("User removed"); utils.userManagement.directory.invalidate(); }, onError: error => toast.error(error.message) });
  if (user?.role !== "admin") return <Card className="border-amber-200 bg-amber-50"><CardContent className="p-8"><h1 className="font-display text-2xl font-semibold text-amber-950">Admin access required</h1><p className="mt-2 text-sm text-amber-800">The user directory is restricted to the Category Leader admin account.</p></CardContent></Card>;
  const rows = directory.data ?? [];
  return <div className="space-y-8"><SectionHeading eyebrow="Administration" title="User directory" description="Review verified accounts, assign Team Leaders and Testers, and remove suspicious or inactive users without exposing credentials." action={<Badge className="border-emerald-200 bg-emerald-50 text-emerald-700">{rows.filter(row => row.accountStatus === "active").length} active</Badge>} /><Card className="border-slate-200 shadow-none"><CardHeader className="border-b border-slate-100 px-6 py-5"><CardTitle className="text-base">Account moderation</CardTitle><p className="mt-1 text-xs text-slate-500">Email/phone OTP verification status is stored server-side. Existing OAuth users were migrated as active and verified.</p></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[980px] text-left text-sm"><thead className="bg-slate-50 text-[11px] uppercase tracking-wider text-slate-500"><tr><th className="px-6 py-3">User</th><th className="px-4 py-3">Verified email</th><th className="px-4 py-3">Verified phone</th><th className="px-4 py-3">Role</th><th className="px-4 py-3">Team parent</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">Active session</th><th className="px-6 py-3 text-right">Actions</th></tr></thead><tbody>{directory.isLoading ? <tr><td colSpan={8} className="px-6 py-16 text-center text-slate-400">Loading directory…</td></tr> : rows.map(row => <tr key={row.id} className="border-t border-slate-100 align-middle"><td className="px-6 py-4"><p className="font-semibold text-slate-800">{row.name || "Unnamed user"}</p><p className="mt-1 text-[11px] text-slate-400">Joined {new Date(row.createdAt).toLocaleDateString()}</p></td><td className="px-4 py-4 text-xs text-slate-600">{row.email || "No email"}</td><td className="px-4 py-4 text-xs text-slate-600">{row.phoneNumber || "No phone"}</td><td className="px-4 py-4"><Select value={row.accountRole} onValueChange={value => roleMutation.mutate({ userId: row.id, accountRole: value as "admin" | "team_leader" | "tester", teamLeaderId: null })}><SelectTrigger className="h-8 w-[135px] text-xs"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="admin">Admin</SelectItem><SelectItem value="team_leader">Team Leader</SelectItem><SelectItem value="tester">Tester</SelectItem></SelectContent></Select></td><td className="px-4 py-4"><Select value={row.teamLeaderId ? String(row.teamLeaderId) : "none"} onValueChange={value => { if (row.accountRole === "tester" && value !== "none") roleMutation.mutate({ userId: row.id, accountRole: "tester", teamLeaderId: Number(value) }); }}><SelectTrigger className="h-8 w-[155px] text-xs"><SelectValue placeholder={row.teamLeader || "None"} /></SelectTrigger><SelectContent><SelectItem value="none">No parent</SelectItem>{(roster.data?.leaders ?? []).map(leader => <SelectItem key={leader.id} value={String(leader.id)}>{leader.name}</SelectItem>)}</SelectContent></Select></td><td className="px-4 py-4"><Badge variant="outline" className={row.accountStatus === "active" && row.isVerified && row.email && row.phoneNumber && row.emailVerified && row.phoneVerified ? "border-emerald-200 bg-emerald-50 text-emerald-700" : row.accountStatus === "blocked" ? "border-rose-200 bg-rose-50 text-rose-700" : "border-amber-200 bg-amber-50 text-amber-700"}>{row.accountStatus === "active" && row.isVerified && row.email && row.phoneNumber && row.emailVerified && row.phoneVerified ? "Dual verified / Active" : row.accountStatus === "active" ? "OAuth / Active" : row.accountStatus === "blocked" ? "Blocked" : "Pending verification"}</Badge></td><td className="px-4 py-4 text-xs text-slate-500">{row.session?.isActive && Date.now() - new Date(row.session.lastSeenAt).getTime() < 15 * 60 * 1000 ? <span className="inline-flex items-center gap-1.5 font-medium text-emerald-700"><span className="h-2 w-2 rounded-full bg-emerald-500" />Active now</span> : row.session?.lastSeenAt ? `Last seen ${new Date(row.session.lastSeenAt).toLocaleString()}` : "No session record"}</td><td className="px-6 py-4"><div className="flex justify-end gap-2"><Button size="sm" variant="outline" className="h-8 border-slate-200 bg-white text-xs" onClick={() => statusMutation.mutate({ userId: row.id, status: row.accountStatus === "blocked" ? "active" : "blocked", isVerified: row.accountStatus === "blocked" ? 1 : 0 })}>{row.accountStatus === "blocked" ? "Unblock" : "Block"}</Button><Button size="sm" variant="ghost" className="h-8 text-xs text-rose-600 hover:bg-rose-50 hover:text-rose-700" disabled={row.id === user.id} onClick={() => { if (window.confirm(`Remove ${row.name || "this user"}?`)) deleteMutation.mutate({ userId: row.id }); }}>Remove</Button></div></td></tr>)}</tbody></table></div>{!rows.length && !directory.isLoading && <div className="p-16 text-center text-sm text-slate-400">No user accounts have been registered yet.</div>}</CardContent></Card></div>;
}

function Assistant() { const [messages, setMessages] = useState<Message[]>([]); const [report, setReport] = useState<AssistantReport | null>(null); const mutation = trpc.assistant.chat.useMutation({ onSuccess: response => { setMessages(prev => [...prev, { role: "assistant", content: response.content }]); if (response.ingestion) { setReport(response.ingestion); toast.success(`Stored ${response.ingestion.stored} tester rows in the database`); } }, onError: error => toast.error(error.message) }); const send = (content: string) => { const next = [...messages, { role: "user" as const, content }]; setMessages(next); mutation.mutate({ messages: next }); }; return <div className="space-y-8"><SectionHeading eyebrow="AI reporting assistant" title="Ask your workspace" description="Give a tester name, OTP count, and project. The assistant finds the existing Team Leader, combines repeated tester entries into one row, and keeps raw report data separate from the roster." /><div className="grid gap-6 xl:grid-cols-[1fr_300px]"><div className="space-y-4"><AIChatBox messages={messages} onSendMessage={send} isLoading={mutation.isPending} height={"min(560px, calc(100vh - 320px))"} emptyStateMessage="Your reporting co-pilot is ready" suggestedPrompts={["Bisma did 50 OTP on Super X", "Bisma did 200 OTP on Inception", "Add tester Ali under Ayesha", "Delete tester Ali"]} />{report && <Card className="border-emerald-200 bg-emerald-50/60 shadow-none"><CardContent className="p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm font-semibold text-emerald-900">Report ready · {report.date}</p><p className="mt-1 text-xs text-emerald-700">{report.stored} tester rows stored · {report.exceptions.length} validation notes</p></div><div className="flex gap-2"><Button size="sm" className="gap-2 bg-slate-950 hover:bg-slate-800" onClick={() => { downloadAssistantWorkbook(report); toast.success("Excel report downloaded"); }}><Download className="h-3.5 w-3.5" />Excel</Button><Button size="sm" variant="outline" className="gap-2 border-emerald-300 bg-white text-emerald-800" onClick={() => { downloadAssistantImage(report); toast.success("Image report downloaded"); }}><Download className="h-3.5 w-3.5" />Image</Button></div></div><div className="mt-4 overflow-x-auto rounded-xl border border-emerald-100 bg-white">{report.payoutRequested ? <table className="w-full min-w-[900px] text-left text-xs"><thead className="bg-sky-50 text-slate-700"><tr><th className="px-3 py-2">Team Leader / Tester</th><th className="px-3 py-2">Role</th><th className="px-3 py-2 text-right">Inception OTP</th><th className="px-3 py-2 text-right">Inception Payout</th><th className="px-3 py-2 text-right">Super X OTP</th><th className="px-3 py-2 text-right">Super X Payout</th><th className="px-3 py-2 text-right">Total OTP</th><th className="px-3 py-2 text-right">Total Payout</th><th className="px-3 py-2">Status</th></tr></thead><tbody>{report.rows.map((row, index) => <tr key={`${row.tester}-${index}`} className="border-t border-slate-100"><td className="px-3 py-2">{row.tester}</td><td className="px-3 py-2">Tester</td><td className="px-3 py-2 text-right">{row.inception}</td><td className="px-3 py-2 text-right">{row.inceptionPayout ?? 0}</td><td className="px-3 py-2 text-right">{row.superX}</td><td className="px-3 py-2 text-right">{row.superXPayout ?? 0}</td><td className="px-3 py-2 text-right font-bold">{row.total}</td><td className="px-3 py-2 text-right font-bold">{row.totalPayout ?? 0}</td><td className="px-3 py-2">Active</td></tr>)}</tbody></table> : <table className="w-full min-w-[580px] text-left text-xs"><thead className="bg-sky-50 text-slate-700"><tr><th className="px-3 py-2">Project</th><th className="px-3 py-2 text-right">Inception</th><th className="px-3 py-2 text-right">Super x</th><th className="px-3 py-2 text-right">Total</th></tr></thead><tbody>{reportMatrix(report.rows).slice(1).map((row, index) => <tr key={`${String(row[0])}-${index}`} className={report.rows.some(item => item.leader === row[0]) || row[0] === "Grand Total" ? "bg-lime-100 font-bold" : "border-t border-slate-100"}><td className="px-3 py-2">{row[0]}</td><td className="px-3 py-2 text-right">{row[1]}</td><td className="px-3 py-2 text-right">{row[2]}</td><td className="px-3 py-2 text-right font-bold">{row[3]}</td></tr>)}</tbody></table>}</div>{report.exceptions.length > 0 && <p className="mt-3 text-[11px] text-amber-700">Validation notes: {report.exceptions.join(" · ")}</p>}</CardContent></Card>}</div><Card className="h-fit border-slate-200 bg-slate-950 text-white shadow-none"><CardContent className="p-6"><Sparkles className="mb-5 h-6 w-6 text-emerald-300" /><p className="text-lg font-semibold tracking-tight">Intelligent raw-data entry.</p><p className="mt-3 text-sm leading-6 text-slate-300">Existing roster names are used to infer Team Leaders. Two project commands for the same tester become one formatted row with separate project columns. Raw report commands never create roster members.</p><div className="mt-6 space-y-3 border-t border-white/10 pt-5 text-xs text-slate-400"><p>✓ Bisma 50 + Bisma 200 = one row</p><p>✓ Team Leader inferred from roster</p><p>✓ Project names preserved</p><p>✓ Excel and PNG match the template</p></div></CardContent></Card></div></div>; }

export default function Home() { const [location, setLocation] = useLocation(); const path = location.split("?")[0]; const go = (next: string) => setLocation(next); if (path === "/login") return <LoginPage />; if (path === "/register") return <RegisterPage />; if (path === "/verify") return <VerifyPage />; if (path === "/daily") return <DailyReport />; if (path === "/payouts") return <Payouts />; if (path === "/roster") return <Roster />; if (path === "/targets") return <Targets />; if (path === "/audit") return <Audit />; if (path === "/assistant") return <Assistant />; if (path === "/admin") return <AdminDashboard />; if (path === "/users") return <UserDirectory />; return <Overview go={go} />; }
